import { useEffect, useRef, useState } from 'react';
import { streamChat, mediaUrl } from '../lib/api';

/** 首页「主编」面板：常驻数字员工的对话入口 + 今日排班。 */
type Job = { id: string; type: string; title: string; at: string; state: string; startedAt?: number; finishedAt?: number };
type PlanItem = { time: string; type: string; title: string; why?: string; gate?: string };
type Card = { id: string; type: 'proposal' | 'review' | 'approval' | 'plan' | 'notice' | 'retro'; title: string; body?: string;
  options?: Array<{ label: string; desc?: string }>; artifacts?: string[]; rhythm?: string[]; items?: PlanItem[] };
type Panel = {
  onDuty: boolean; workStart: number; workEnd: number; date: string;
  total: number; done: number; jobs: Job[]; pendingApprovals: number; cards?: Card[];
  mode?: 'auto' | 'manual';
  isToday?: boolean;
  lanes?: Record<string, { busy: boolean; pending: number }>;
  plan?: { version: number; status: string; replans?: unknown[] } | null;
  session?: Array<{ ts: number; actor: 'agent' | 'human' | 'system'; content: string; type?: string }>;
};
type Msg = { role: 'user' | 'assistant'; content: string; ts: number; actor?: string };

const KEY = 'agentd_panel_msgs';
const STATE_LABEL: Record<string, string> = { pending: '待办', running: '进行中', done: '完成', skipped: '跳过' };

export default function ConciergePanel() {
  const [data, setData] = useState<Panel | null>(null);
  const [msgs, setMsgs] = useState<Msg[]>(() => {
    try { return JSON.parse(localStorage.getItem(KEY) || '[]') as Msg[]; } catch { return []; }
  });
  const [text, setText] = useState('');
  const [busy, setBusy] = useState(false);
  const [cards, setCards] = useState<Card[]>([]);
  const [revising, setRevising] = useState(false);
  const [mountedDate] = useState<string>(() => {
    const d = new Date();
    const pad = (n: number) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  });
  const [date, setDate] = useState<string>(() => {
    const d = new Date();
    const pad = (n: number) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  });
  const applyPanel = (d: Panel) => {
    setData(d); setCards(d.cards ?? []);
    if (d.session?.length) {
      setMsgs(d.session.map((m) => ({ role: m.actor === 'human' ? 'user' as const : 'assistant' as const, content: m.content, ts: m.ts, actor: m.actor })));
    }
  };
  const ctl = useRef<AbortController | null>(null);
  const endRef = useRef<HTMLDivElement>(null);

  // 跨天：如果还停在"打开页面那天"，自动翻到新的今天
  useEffect(() => {
    const t = setInterval(() => {
      const d = new Date();
      const pad = (n: number) => String(n).padStart(2, '0');
      const today = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
      setDate((cur) => (cur === mountedDate && today !== mountedDate ? today : cur));
    }, 30000);
    return () => clearInterval(t);
  }, [mountedDate]);

  useEffect(() => {
    let alive = true;
    const load = () => {
      fetch(`/api/agentd/panel?date=${date}`).then((r) => r.json()).then((d: Panel) => { if (alive) applyPanel(d); }).catch(() => {});
    };
    load();
    const t = setInterval(load, 60000);
    return () => { alive = false; clearInterval(t); };
  }, [date]);

  useEffect(() => {
    try { localStorage.setItem(KEY, JSON.stringify(msgs.slice(-100))); } catch { /* ignore */ }
    endRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [msgs]);

  const send = () => {
    const t = text.trim();
    if (!t || busy) return;
    setText('');
    if (revising) {
      setRevising(false); setBusy(true);
      void fetch('/api/agentd/plan/revise', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ instruction: t }) })
        .then(() => fetch('/api/agentd/panel')).then((r) => r.json()).then((d: Panel) => applyPanel(d))
        .finally(() => setBusy(false));
      return;
    }
    setBusy(true);
    setMsgs((m) => [...m, { role: 'user', content: t, ts: Date.now() }, { role: 'assistant', content: '', ts: Date.now() }]);
    ctl.current = streamChat(
      t, undefined, `daily-${data?.date ?? new Date().toISOString().slice(0, 10)}`,
      (delta) => setMsgs((m) => {
        const n = [...m];
        n[n.length - 1] = { ...n[n.length - 1], content: n[n.length - 1].content + delta };
        return n;
      }),
      () => {
        setBusy(false);
        fetch(`/api/agentd/panel?date=${date}`).then((r) => r.json()).then((d: Panel) => { applyPanel(d); }).catch(() => {});
      },
      (err) => { setMsgs((m) => { const n = [...m]; n[n.length - 1] = { ...n[n.length - 1], content: `❌ ${err.message}` }; return n; }); setBusy(false); },
    );
  };

  const resolve = async (card: Card, action: string, payload?: unknown) => {
    try {
      await fetch(`/api/agentd/cards/${encodeURIComponent(card.id)}/resolve`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, payload }),
      });
      setCards((cs) => cs.filter((c) => c.id !== card.id));
      const r = await fetch(`/api/agentd/panel?date=${date}`); const d = (await r.json()) as Panel;
      setData(d); setCards(d.cards ?? []);
    } catch { /* ignore */ }
  };

  const toggleMode = async () => {
    const next = (data?.mode ?? 'auto') === 'auto' ? 'manual' : 'auto';
    await fetch('/api/agentd/mode', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ mode: next, by: 'human' }) }).catch(() => {});
    const r = await fetch(`/api/agentd/panel?date=${date}`); applyPanel((await r.json()) as Panel);
  };

  const jobs = data?.jobs?.slice(0, 5) ?? [];
  const todayStr = (): string => { const d = new Date(); const pad = (n: number) => String(n).padStart(2, '0'); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`; };
  const shiftDate = (d: string, delta: number): string => { const t = new Date(`${d}T12:00:00`); t.setDate(t.getDate() + delta); return `${t.getFullYear()}-${String(t.getMonth() + 1).padStart(2, '0')}-${String(t.getDate()).padStart(2, '0')}`; };
  return (
    <div className="concierge card">
      <div className="concierge-head">
        <div className="concierge-title">
          <span className={`concierge-dot ${data?.onDuty ? 'on' : 'off'}`} />
          主编
          <span className="concierge-sub">
            {data ? (data.onDuty ? `在岗 · 今日 ${data.done}/${data.total}` : '已下班') : '连接中…'}
            {data?.pendingApprovals ? ` · 待审批 ${data.pendingApprovals}` : ''}
          </span>
        </div>
        <div className="concierge-right">
          <div className="concierge-date">
            <button onClick={() => setDate(shiftDate(date, -1))}>‹</button>
            <span>{date}</span>
            <button onClick={() => setDate(shiftDate(date, 1))} disabled={date >= todayStr()}>›</button>
          </div>
          <button className="concierge-away" onClick={async () => {
            setBusy(true);
            try {
              await fetch('/api/agentd/away', { method: 'POST' });
              const r = await fetch(`/api/agentd/panel?date=${date}`); applyPanel((await r.json()) as Panel);
            } finally { setBusy(false); }
          }}>老板离开我自己干</button>
          <button className={`concierge-mode is-${data?.mode ?? 'auto'}`} onClick={toggleMode}>
            {data?.mode === 'manual' ? '我执行' : '主编执行'}
          </button>
          <div className="concierge-hours">
            {data?.plan ? `计划 v${data.plan.version}${data.plan.replans?.length ? ` · 调整 ${data.plan.replans.length} 次` : ''}` : (data ? `${data.workStart}:00–${data.workEnd}:00` : '')}
          </div>
        </div>
      </div>

      {data?.lanes && (
        <div className="concierge-lanes">
          {[['content', '内容'], ['ops', '运营'], ['improve', '改进']].map(([k, label]) => {
            const l = data.lanes?.[k];
            return (
              <span key={k} className={`lane-chip ${l?.busy ? 'is-busy' : ''}`}>
                <i />{label} {l?.busy ? '运行中' : `${l?.pending ?? 0} 待办`}
              </span>
            );
          })}
        </div>
      )}

      {jobs.length > 0 && (
        <div className="concierge-jobs">
          {jobs.map((j) => (
            <div key={j.id} className={`concierge-job is-${j.state}`}>
              <span className="cj-time">{j.at}</span>
              <span className="cj-title">
                {j.title}
                {j.finishedAt && <span className="cj-actual">实际 {new Date(j.finishedAt).toTimeString().slice(0, 5)}</span>}
              </span>
              <span className="cj-state">{STATE_LABEL[j.state] ?? j.state}</span>
            </div>
          ))}
        </div>
      )}

      {cards.map((c) => (
        <div key={c.id} className={`concierge-card is-${c.type}`}>
          <div className="cc-title">{c.type === 'proposal' ? '🗳 ' : c.type === 'approval' ? '🚀 ' : '🎬 '}{c.title}</div>
          {c.body && <div className="cc-body">{c.body}</div>}
          {(c.artifacts?.length ?? 0) > 0 && (
            <div className="cc-media">
              {c.artifacts!.filter((a) => a.endsWith('.mp4')).slice(0, 1).map((a) => (
                <video key={a} src={mediaUrl(a)} controls preload="metadata" />
              ))}
              {c.artifacts!.filter((a) => /\.(png|jpe?g|webp)$/i.test(a)).slice(0, 4).map((a) => (
                <img key={a} src={mediaUrl(a)} alt="" loading="lazy" />
              ))}
            </div>
          )}
          {c.type === 'retro' && (
            <div className="cc-actions">
              <button className="cc-ok" onClick={() => resolve(c, 'approve')}>采纳建议</button>
              <button className="cc-no" onClick={() => resolve(c, 'reject')}>暂不</button>
            </div>
          )}
          {c.type === 'notice' && (
            <div className="cc-actions">
              <button className="cc-ok" onClick={() => resolve(c, 'ok')}>知道了</button>
            </div>
          )}
          {c.type === 'plan' && (
            <div className="cc-plan">
              {c.rhythm?.length ? <div className="cc-rhythm">{c.rhythm.join(' · ')}</div> : null}
              <div className="cc-items">
                {(c.items ?? []).map((it, i) => (
                  <div key={i} className="cc-item">
                    <span className="cc-item-time">{it.time}</span>
                    <span className="cc-item-title">{it.title}</span>
                    {it.gate && it.gate !== 'none' && <span className={`cc-gate is-${it.gate}`}>{it.gate === 'approval' ? '需审批' : '需审核'}</span>}
                  </div>
                ))}
              </div>
              <div className="cc-actions">
                <button className="cc-ok" onClick={() => resolve(c, 'approve')}>批准开工</button>
                <button className="cc-no" onClick={() => { setRevising(true); }}>调整计划</button>
                <button className="cc-no" onClick={() => resolve(c, 'reject')}>打回重排</button>
              </div>
            </div>
          )}
          {c.type === 'proposal' && c.options?.length ? (
            <div className="cc-options">
              {c.options.map((o) => (
                <button key={o.label} className="cc-opt" onClick={() => resolve(c, 'choose', { choice: o.label })}>
                  <span className="cc-opt-label">{o.label}</span>
                  {o.desc && <span className="cc-opt-desc">{o.desc}</span>}
                </button>
              ))}
            </div>
          ) : (
            <div className="cc-actions">
              <button className="cc-ok" onClick={() => resolve(c, 'approve')}>通过</button>
              <button className="cc-no" onClick={() => resolve(c, 'reject')}>打回</button>
            </div>
          )}
        </div>
      ))}

      <div className="concierge-chat">
        {msgs.length === 0 && <div className="concierge-empty">和主编说点什么：今天做什么、数据怎么样、哪里卡住了。</div>}
        {msgs.map((m, i) => (
          <div key={i} className={`concierge-msg is-${m.role}`}>
            <span className="cm-role">{m.role === 'user' ? '你' : '主编'}</span>
            <span className="cm-text">{m.content || (m.role === 'assistant' && busy ? '…' : '')}</span>
          </div>
        ))}
        <div ref={endRef} />
      </div>

      {data?.isToday === false ? (
        <div className="concierge-empty">历史记录 · 只读</div>
      ) : null}
      <div className="concierge-input">
        <input
          disabled={data?.isToday === false}
          value={text}
          placeholder="给主编发消息…"
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); } }}
        />
        <button onClick={send} disabled={busy || !text.trim()}>{busy ? '…' : '发送'}</button>
      </div>
    </div>
  );
}
