import { useEffect, useRef, useState } from 'react';
import { getRun, stopRun, type RunState } from '../lib/runs';

const ICON: Record<string, string> = { pending: '○', running: '●', done: '✓', failed: '✗', skipped: '–' };

export default function RunCard({ runId, onClose }: { runId: string; onClose: () => void }) {
  const [state, setState] = useState<RunState | null>(null);
  const [err, setErr] = useState('');
  const timer = useRef<number | null>(null);

  useEffect(() => {
    let alive = true;
    const tick = async () => {
      try {
        const s = await getRun(runId);
        if (!alive) return;
        setState(s);
        setErr('');
        if (s.status === 'running') {
          timer.current = window.setTimeout(tick, 2500);
        }
      } catch (e) {
        if (!alive) return;
        setErr((e as Error).message);
        timer.current = window.setTimeout(tick, 4000);
      }
    };
    tick();
    return () => {
      alive = false;
      if (timer.current) window.clearTimeout(timer.current);
    };
  }, [runId]);

  const running = state?.status === 'running';
  const label = !state ? '连接运行态…'
    : state.status === 'done' ? '已完成'
    : state.status === 'failed' ? '失败'
    : state.status === 'stopped' ? '已停止'
    : '正在制作';

  return (
    <div className={`run-card ${state?.status || ''}`} role="status">
      <div className="run-head">
        <span className="run-title">{label} · {state?.templateId || ''}</span>
        <span className="run-pct">{state?.percent ?? 0}%</span>
        {running && (
          <button className="run-stop" onClick={() => void stopRun(runId)}>停止</button>
        )}
        {!running && <button className="run-stop" onClick={onClose}>关闭</button>}
      </div>
      <div className="run-bar"><span style={{ width: `${state?.percent ?? 0}%` }} /></div>
      <div className="run-stages">
        {(state?.stages || []).map((s) => (
          <div key={s.id} className={`run-stage ${s.state}`} title={s.error || s.output || ''}>
            <span className="run-dot">{ICON[s.state] || '○'}</span>
            <span className="run-sid">{s.id}</span>
            <span className="run-role">{s.role}</span>
          </div>
        ))}
      </div>
      {state?.critic && (
        <div className="run-critic">
          评审：{state.critic.score ?? "?"} 分 · {state.critic.verdict ?? "?"}
          {state.reviseCount ? ` · 已返工 ${state.reviseCount} 次` : ""}
        </div>
      )}
      {state?.status === 'failed' && (
        <div className="run-actions">
          <button
            className="run-retry"
            onClick={async () => {
              setErr('');
              try {
                const r = await fetch(`/api/runs/${runId}/retry`, { method: 'POST' });
                if (!r.ok) throw new Error(`HTTP ${r.status}`);
                const s = await getRun(runId);
                setState(s);
                timer.current = window.setTimeout(() => { void (async () => {
                  const n = await getRun(runId); setState(n);
                })(); }, 2500);
              } catch (e) { setErr(String(e)); }
            }}
          >
            断点续跑
          </button>
        </div>
      )}
      {state?.error && <div className="run-err">{state.error}</div>}
      {err && <div className="run-err">{err}</div>}
      {state?.outputs?.length ? (
        <div className="run-out">产物：{state.outputs.map((p) => p.split('/').pop()).join(' · ')}</div>
      ) : null}
    </div>
  );
}
