import { useState, useRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import MessageBubble from './MessageBubble';
import QuestionCards from './QuestionCards';
import BrushEntry from './BrushEntry';
import CommandPalette from './CommandPalette';
import RunCard from './RunCard';
import { startRun } from '../lib/runs';
import { getTemplate, type TemplateInput, type TemplateSummary } from '../lib/templates';
import type { ChatSession, ChatMessage, StreamState } from '../lib/store';
import { uploadFiles, adoptOversize } from '../lib/api';
import type { UploadedFile } from '../lib/api';
import { IconArrowUp, IconStop, IconPlus, IconFile } from './icons';

interface ChatPageProps {
  apiDirect: boolean;
  session: ChatSession;
  stream?: StreamState;          // 进行中的流式态（来自 App，切页也不丢）
  onSend: (displayText: string, attachments?: UploadedFile[], templateId?: string, variables?: Record<string, unknown>) => void;
  onStop: () => void;
  onResend: (
    userIndex: number,
    displayText: string,
    attachments?: UploadedFile[],
    legacyAgentText?: string,
  ) => void; // 重试：仅对最后一轮
  onQuestionAnswered?: (questionId: string, answerText?: string) => void;   // 某道问答题提交成功（App 记录答过，重放不再出现）
}

// 空态推荐（贴合 Avatar 社媒创作场景）

function StepTimeline({ steps, live }: { steps: Array<{ id: string; name: string; status?: string; ms?: number; args?: string }>; live?: boolean }) {
  if (!steps.length) return null;
  return (
    <div className={`step-timeline${live ? ' is-live' : ''}`}>
      {steps.map((s) => (
        <div key={s.id} className={`step-chip ${s.status === 'error' ? 'is-error' : s.status === 'ok' ? 'is-ok' : 'is-running'}`}
             title={s.args || ''}>
          <span className="step-dot" />
          <span className="step-name">{s.name}</span>
          {typeof s.ms === 'number' && s.ms > 0 && <span className="step-ms">{s.ms < 1000 ? `${s.ms}ms` : `${(s.ms / 1000).toFixed(1)}s`}</span>}
        </div>
      ))}
    </div>
  );
}

const SUGGESTIONS = [
  { icon: '🔥', title: '蹭个热点', prompt: '看看现在微博和抖音有什么热搜，挑几个适合我做二创的选题' },
  { icon: '✍️', title: '写小红书文案', prompt: '帮我写一条小红书种草文案，主题先问我' },
  { icon: '🎴', title: '做金句卡片', prompt: '把一句走心的话做成一张适合发朋友圈的金句卡片' },
  { icon: '🎬', title: '口播脚本', prompt: '帮我写一条 60 秒的口播短视频脚本，主题先问我' },
];

function greeting(): string {
  const h = new Date().getHours();
  const g = h < 6 ? '夜深了' : h < 12 ? '上午好' : h < 14 ? '中午好' : h < 18 ? '下午好' : '晚上好';
  return `${g}，想创作点什么？`;
}

export default function ChatPage({ apiDirect, session, stream, onSend, onStop, onResend, onQuestionAnswered }: ChatPageProps) {
  const [input, setInput] = useState('');
  const [paletteOpen, setPaletteOpen] = useState(false);
  const [pendingTemplate, setPendingTemplate] = useState<TemplateSummary | null>(null);
  const [templateVars, setTemplateVars] = useState<Record<string, string>>({});
  const [templateInputs, setTemplateInputs] = useState<TemplateInput[]>([]);
  const [runId, setRunId] = useState<string | null>(null);
  const [runStarting, setRunStarting] = useState(false);
  const [attachments, setAttachments] = useState<UploadedFile[]>([]);
  const [uploading, setUploading] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const [maxMb, setMaxMb] = useState(50);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isComposingRef = useRef(false);

  const isStreaming = !!stream;
  const isEmpty = session.messages.length === 0 && !isStreaming;

  useEffect(() => {
    fetch('/api/upload/limits').then((r) => r.json())
      .then((d) => { if (d?.max_mb) setMaxMb(d.max_mb); }).catch(() => {});
  }, []);

  const doUpload = async (fs: FileList | File[]) => {
    const arr = Array.from(fs);
    if (!arr.length) return;
    const cap = maxMb * 1024 * 1024;
    const big = arr.filter((f) => f.size > cap);
    const small = arr.filter((f) => f.size <= cap);

    if (big.length) {
      // 超限：不走上传通道，复制进收件箱后作为普通附件（界面零新增元素）
      setUploading(true);
      try {
        const saved = await adoptOversize(big, session.id);
        setAttachments((a) => [...a, ...saved]);
      } catch (err) {
        alert((err as Error).message || '超限文件处理失败');
      } finally {
        setUploading(false);
      }
    }
    if (!small.length) return;
    setUploading(true);
    try {
      const saved = await uploadFiles(small, session.id);
      setAttachments((a) => [...a, ...saved]);
    } catch (err) {
      alert((err as Error).message || '上传失败');
    } finally {
      setUploading(false);
    }
  };
  const onDrop = (e: React.DragEvent) => {
    e.preventDefault(); setDragOver(false);
    if (e.dataTransfer.files?.length) doUpload(e.dataTransfer.files);
  };
  const onPaste = (e: React.ClipboardEvent) => {
    if (e.clipboardData.files?.length) { e.preventDefault(); doUpload(e.clipboardData.files); }
  };
  const removeAttachment = (path: string) => setAttachments((a) => a.filter((x) => x.path !== path));

  useEffect(() => {
    if (!isEmpty) messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [session.messages, stream?.content, stream?.thinking, stream?.activity, stream?.stillWorking, isEmpty]);

  useEffect(() => {
    const el = textareaRef.current;
    if (el) {
      el.style.height = 'auto';
      el.style.height = Math.min(el.scrollHeight, 180) + 'px';
    }
  }, [input]);

  const handleSend = () => {
    const trimmed = input.trim();
    if ((!trimmed && attachments.length === 0) || isStreaming || uploading) return;
    // 附件通过结构化字段发送；用户消息气泡只显示用户实际输入的文字。
    const tplId = pendingTemplate?.id;
    const vars = Object.fromEntries(Object.entries(templateVars).filter(([, v]) => v.trim()));
    setPendingTemplate(null);
    setTemplateVars({});
    onSend(trimmed, attachments, tplId, vars);
    setInput('');
    setAttachments([]);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    // 输入法确认候选词/英文的回车交给输入法处理，不能触发发送。
    // 部分浏览器先触发 compositionend，此时仍需用 229 识别输入法按键。
    if (isComposingRef.current || e.nativeEvent.isComposing || e.nativeEvent.keyCode === 229) return;
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const inputBox = (hero: boolean) => (
    <div className={`composer ${hero ? 'composer-hero' : ''} ${dragOver ? 'composer-drag' : ''}`}
      onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
      onDragLeave={(e) => { e.preventDefault(); setDragOver(false); }}
      onDrop={onDrop}>
      {attachments.length > 0 && (
        <div className="composer-attachments">
          {attachments.map((a) => (
            <span key={a.path} className="attach-chip" title={a.path}>
              <IconFile size={12} /> <span className="attach-name">{a.name}</span>
              <button className="attach-x" onClick={() => removeAttachment(a.path)} title="移除">×</button>
            </span>
          ))}
        </div>
      )}
      {runId && <RunCard runId={runId} onClose={() => setRunId(null)} />}
      {pendingTemplate && (
        <div className="composer-template-chip">
          <span>{pendingTemplate.emoji || '✦'} 模板：{pendingTemplate.name}</span>
          <button
            onClick={() => { setPendingTemplate(null); setTemplateVars({}); setTemplateInputs([]); }}
            aria-label="移除模板"
          >×</button>
          <button
            className="composer-run-btn"
            disabled={runStarting || isStreaming}
            onClick={async () => {
              const tpl = pendingTemplate;
              if (!tpl) return;
              const vars = Object.fromEntries(Object.entries(templateVars).filter(([, v]) => v.trim()));
              setRunStarting(true);
              try {
                const rid = await startRun(tpl.id, vars, input.trim());
                setRunId(rid);
              } catch (e) {
                setRunStarting(false);
                // 失败时退回对话，让用户知道
                onSend(`启动流水线失败：${(e as Error).message}`, []);
                return;
              }
              setRunStarting(false);
            }}
          >{runStarting ? '启动中…' : '▶ 跑流水线'}</button>
        </div>
      )}
      {pendingTemplate && templateInputs.some((i) => i.type === 'text' || i.type === 'select') && (
        <div className="composer-vars">
          {templateInputs
            .filter((i) => i.type === 'text' || i.type === 'select')
            .map((i) => (
              <label key={i.key} className="composer-var">
                <span>{i.label}{i.required ? ' *' : ''}</span>
                {i.type === 'select' && i.options?.length ? (
                  <select
                    value={templateVars[i.key] || ''}
                    onChange={(e) => setTemplateVars((v) => ({ ...v, [i.key]: e.target.value }))}
                  >
                    <option value="">选择…</option>
                    {i.options.map((o) => <option key={o} value={o}>{o}</option>)}
                  </select>
                ) : (
                  <input
                    value={templateVars[i.key] || ''}
                    placeholder={i.label}
                    onChange={(e) => setTemplateVars((v) => ({ ...v, [i.key]: e.target.value }))}
                  />
                )}
              </label>
            ))}
          {templateInputs.some((i) => i.type === 'files') && (
            <span className="composer-vars-hint">素材用下方「素材」按钮上传</span>
          )}
        </div>
      )}
      <div className="composer-top">
        {apiDirect ? <span className="composer-hint">API 直连 · 文字与附件分析</span>
          : <BrushEntry onPick={(t) => { setInput(t); requestAnimationFrame(() => textareaRef.current?.focus()); }} />}
        <textarea
          ref={textareaRef}
          className="chat-input"
          placeholder={dragOver ? '松手上传素材…' : hero ? '把你的想法告诉我，选题 / 文案 / 卡片 / 视频 / 发布都行…（可拖入图片/文档当素材）' : '发消息…（Enter 发送，Shift+Enter 换行，可拖入/粘贴素材）'}
          value={input}
          onChange={(e) => {
            const v = e.target.value;
            setInput(v);
            if (v === '/' && !isStreaming) setPaletteOpen(true);
            if (paletteOpen && !v.startsWith('/')) setPaletteOpen(false);
          }}
          onCompositionStart={() => { isComposingRef.current = true; }}
          onCompositionEnd={() => { isComposingRef.current = false; }}
          onBlur={() => { isComposingRef.current = false; }}
          onKeyDown={handleKeyDown}
          onPaste={onPaste}
          rows={1}
          autoFocus={hero}
        />
      </div>
      <input ref={fileInputRef} type="file" multiple hidden
        onChange={(e) => { if (e.target.files) doUpload(e.target.files); e.target.value = ''; }} />
      <div className="composer-bar">
        <button className="composer-attach-btn" onClick={() => setPaletteOpen(true)} disabled={isStreaming} title="选择模板（输入 / 也可以）">
          ✦ 模板
        </button>
        <button className="composer-attach-btn" onClick={() => fileInputRef.current?.click()}
          disabled={isStreaming || uploading} title={`添加素材（图片/文档）；超过 ${maxMb}MB 的大文件将自动存为本地素材（不走上传）`}>
          <IconPlus size={15} /> {uploading ? '上传中…' : '素材'}
        </button>
        <span className="composer-hint">{isStreaming ? '生成中…' : 'Enter 发送 · Shift+Enter 换行'}</span>
        {isStreaming ? (
          <button className="send-btn" onClick={onStop} title="停止生成"><IconStop size={15} /></button>
        ) : (
          <button className="send-btn" onClick={handleSend} disabled={(!input.trim() && !attachments.length) || uploading} title="发送"><IconArrowUp size={17} /></button>
        )}
      </div>
      {createPortal(
        <CommandPalette
          open={paletteOpen}
          onClose={() => setPaletteOpen(false)}
          onPick={(tpl, kind) => {
            setPaletteOpen(false);
            if (kind === 'build') {
              setInput('/构建模板 ');
            } else if (tpl) {
              setPendingTemplate(tpl);
              setTemplateVars({});
              setTemplateInputs([]);
              setInput('');
              getTemplate(tpl.id)
                .then((d) => setTemplateInputs(d.meta.inputs || []))
                .catch(() => setTemplateInputs([]));
            }
            requestAnimationFrame(() => textareaRef.current?.focus());
          }}
        />,
        document.body,
      )}
    </div>
  );

  // ---- 空态：居中欢迎页 ----
  if (isEmpty) {
    return (
      <div className="chat-page">
        <div className="chat-hero">
          <div className="chat-hero-brand">
            <img src="./static/avatar-mark.svg" alt="" />
            <span>Avatar</span>
          </div>
          <h1 className="chat-hero-title">{greeting()}</h1>
          <p className="chat-hero-sub">{apiDirect ? 'API 直连：写文案、策划选题、分析附件。本机工具和自动发布未启用。'
            : '从选题到发布，一站式帮你把想法做成能发的内容。'}</p>
          {inputBox(true)}
          <div className="suggestions">
            {SUGGESTIONS.filter((s) => !apiDirect || ['写小红书文案', '口播脚本'].includes(s.title)).map((s) => (
              <button key={s.title} className="card card-hover suggestion-card"
                onClick={() => { if (!isStreaming) onSend(s.prompt); }}>
                <span className="suggestion-icon">{s.icon}</span>
                <span className="suggestion-body">
                  <span className="suggestion-title">{s.title}</span>
                  <span className="suggestion-text">{s.prompt}</span>
                </span>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // ---- 对话态 ----
  const displayMessages: ChatMessage[] = [...session.messages];
  if (isStreaming) displayMessages.push({ role: 'assistant', content: stream!.content || '' });

  return (
    <div className="chat-page">
      <div className="chat-messages">
        <div className="chat-thread">
          {displayMessages.map((msg, i) => {
            const isLast = i === displayMessages.length - 1;
            const live = isStreaming && isLast && msg.role === 'assistant';
            const isFinal = !live && i < session.messages.length;
            let actions;
            if (isFinal) {
              const copy = () => navigator.clipboard?.writeText(msg.content);
              // 只允许对「最后一轮」重试，契合 OpenClaw append-only 模型（不改写历史）；已移除编辑
              const isLastFinal = i === session.messages.length - 1;
              if (msg.role === 'user') {
                actions = {
                  onCopy: copy,
                  onRetry: isLastFinal
                    ? () => onResend(i, msg.content, msg.attachments, msg.agentContent)
                    : undefined,
                  canModify: !isStreaming,
                };
              } else {
                const pi = i - 1;
                const prevUser = pi >= 0 && session.messages[pi]?.role === 'user' ? session.messages[pi] : null;
                actions = {
                  onCopy: copy,
                  onRetry: (isLastFinal && prevUser)
                    ? () => onResend(pi, prevUser.content, prevUser.attachments, prevUser.agentContent)
                    : undefined,
                  canModify: !isStreaming,
                };
              }
            }
            return (
              <MessageBubble
                key={`${i}-${msg.role}`}
                message={msg}
                isStreaming={live}
                thinking={live ? stream!.thinking : ''}
                activity={live ? stream!.activity : ''}
                stillWorking={live ? stream!.stillWorking : ''}
                actions={actions}
              />
            );
          })}
          {(stream?.steps?.length ?? 0) > 0 && <StepTimeline steps={stream!.steps!} live />}
          {(stream?.questions?.length ?? 0) > 0 && (
            <QuestionCards questions={stream!.questions || []} onDone={(qid, text) => onQuestionAnswered?.(qid, text)} />
          )}
          <div ref={messagesEndRef} />
        </div>
      </div>

      <div className="chat-input-area">
        <div className="chat-input-inner">{inputBox(false)}</div>
      </div>
    </div>
  );
}
