import { BASE } from './api';

export interface RunStage {
  id: string;
  role: string;
  state: 'pending' | 'running' | 'done' | 'failed' | 'skipped';
  output?: string | null;
  error?: string | null;
}

export interface RunState {
  runId: string;
  templateId: string;
  templateVersion?: string;
  variables?: Record<string, unknown>;
  status: 'running' | 'done' | 'failed' | 'stopped';
  percent: number;
  stages: RunStage[];
  outputs?: string[];
  error?: string | null;
  stopRequested?: boolean;
  critic?: { score?: number; verdict?: string; issues?: unknown[] } | null;
  reviseCount?: number;
}

export async function startRun(templateId: string, variables: Record<string, unknown>, message = ''): Promise<string> {
  const res = await fetch(`${BASE}/api/templates/${encodeURIComponent(templateId)}/run`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ variables, message }),
  });
  if (!res.ok) throw new Error(`启动失败（${res.status}）`);
  const data = (await res.json()) as { runId: string };
  return data.runId;
}

export async function getRun(runId: string): Promise<RunState> {
  const res = await fetch(`${BASE}/api/runs/${encodeURIComponent(runId)}`);
  if (!res.ok) throw new Error(`运行状态读取失败（${res.status}）`);
  return (await res.json()) as RunState;
}

export async function stopRun(runId: string): Promise<void> {
  await fetch(`${BASE}/api/runs/${encodeURIComponent(runId)}/stop`, { method: 'POST' });
}
