import { useEffect, useMemo, useRef, useState } from 'react';
import { listTemplates, type TemplateSummary } from '../lib/templates';

interface Props {
  open: boolean;
  onClose: () => void;
  onPick: (tpl: TemplateSummary | null, kind: 'template' | 'build') => void;
}

const RECENT_KEY = 'avatar_recent_templates';

function readRecent(): string[] {
  try {
    const raw = localStorage.getItem(RECENT_KEY);
    return raw ? (JSON.parse(raw) as string[]) : [];
  } catch {
    return [];
  }
}

export function pushRecent(id: string) {
  try {
    const list = [id, ...readRecent().filter((x) => x !== id)].slice(0, 4);
    localStorage.setItem(RECENT_KEY, JSON.stringify(list));
  } catch { /* ignore */ }
}

export default function CommandPalette({ open, onClose, onPick }: Props) {
  const [items, setItems] = useState<TemplateSummary[]>([]);
  const [query, setQuery] = useState('');
  const [active, setActive] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!open) return;
    setQuery('');
    setActive(0);
    setLoading(true);
    setError('');
    listTemplates()
      .then((list) => {
        const recent = readRecent();
        const rank = (id: string) => (recent.includes(id) ? recent.indexOf(id) : 99);
        const sorted = [...list].sort((a, b) => rank(a.id) - rank(b.id) || (b.uses || 0) - (a.uses || 0));
        setItems(sorted);
      })
      .catch((e: Error) => setError(e.message))
      .finally(() => setLoading(false));
    requestAnimationFrame(() => inputRef.current?.focus());
  }, [open]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return items;
    return items.filter((t) => `${t.id} ${t.name} ${t.promise}`.toLowerCase().includes(q));
  }, [items, query]);

  // 末尾固定一项「构建新模板」
  const rows = useMemo(
    () => [
      ...filtered.map((t) => ({ kind: 'template' as const, tpl: t })),
      { kind: 'build' as const, tpl: null },
    ],
    [filtered],
  );

  useEffect(() => {
    if (active >= rows.length) setActive(Math.max(0, rows.length - 1));
  }, [rows.length, active]);

  if (!open) return null;

  const pick = (idx: number) => {
    const row = rows[idx];
    if (!row) return;
    if (row.kind === 'template' && row.tpl) pushRecent(row.tpl.id);
    onPick(row.tpl, row.kind);
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') { e.preventDefault(); onClose(); return; }
    if (e.key === 'ArrowDown') { e.preventDefault(); setActive((i) => Math.min(i + 1, rows.length - 1)); return; }
    if (e.key === 'ArrowUp') { e.preventDefault(); setActive((i) => Math.max(i - 1, 0)); return; }
    if (e.key === 'Enter') { e.preventDefault(); pick(active); }
  };

  return (
    <div className="cmd-backdrop" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="cmd-panel" role="dialog" aria-modal="true" aria-label="选择模板">
        <div className="cmd-search">
          <span className="cmd-slash">/</span>
          <input
            ref={inputRef}
            value={query}
            placeholder="搜索模板，或输入 /构建模板"
            onChange={(e) => { setQuery(e.target.value); setActive(0); }}
            onKeyDown={onKeyDown}
          />
          <span className="cmd-esc">Esc</span>
        </div>

        <div className="cmd-list" role="listbox">
          {loading && <div className="cmd-empty">加载中…</div>}
          {error && <div className="cmd-empty cmd-error">{error}</div>}
          {!loading && !error && filtered.length === 0 && (
            <div className="cmd-empty">没有匹配的模板，试试「构建新模板」</div>
          )}
          {filtered.map((t, i) => (
            <button
              key={t.id}
              role="option"
              aria-selected={i === active}
              className={`cmd-item ${i === active ? 'on' : ''}`}
              onMouseEnter={() => setActive(i)}
              onClick={() => pick(i)}
            >
              <span className="cmd-emoji">{t.emoji || '📄'}</span>
              <span className="cmd-main">
                <span className="cmd-name">{t.name}</span>
                <span className="cmd-sub">
                  {t.duration ? `${Math.round(t.duration[0] / 60 * 10) / 10}–${Math.round(t.duration[1] / 60 * 10) / 10} 分钟` : ''}
                  {t.uses ? ` · 用过 ${t.uses} 次` : ''}
                </span>
              </span>
              <span className="cmd-promise">{t.promise}</span>
            </button>
          ))}
          <button
            role="option"
            aria-selected={active === rows.length - 1}
            className={`cmd-item cmd-build ${active === rows.length - 1 ? 'on' : ''}`}
            onMouseEnter={() => setActive(rows.length - 1)}
            onClick={() => pick(rows.length - 1)}
          >
            <span className="cmd-emoji">✨</span>
            <span className="cmd-main">
              <span className="cmd-name">构建新模板</span>
              <span className="cmd-sub">从已有成片蒸馏</span>
            </span>
          </button>
        </div>

        <div className="cmd-foot">↑↓ 选择 · Enter 确认 · Esc 关闭</div>
      </div>
    </div>
  );
}
