import { BASE } from './api';

export interface TemplateSummary {
  id: string;
  version: string;
  name: string;
  emoji?: string;
  promise: string;
  duration?: [number, number] | null;
  ratio?: string | null;
  uses?: number;
  rating?: number | null;
  updated_at?: string | null;
}

export interface TemplateInput {
  key: string; label: string;
  type: 'text' | 'files' | 'persona' | 'select';
  required?: boolean; min?: number; options?: string[];
}

export interface TemplateDetail {
  meta: TemplateSummary & { inputs?: TemplateInput[]; pipeline?: string[]; checklist?: string[]; publish?: unknown };
  playbook?: string;
  skeleton?: { beats?: { id: string; start: number; end: number; purpose: string; visual?: string }[] };
  checklist?: string;
  metrics?: Record<string, unknown>;
}

export async function listTemplates(q = ''): Promise<TemplateSummary[]> {
  const res = await fetch(`${BASE}/api/templates?q=${encodeURIComponent(q)}`);
  if (!res.ok) throw new Error(`模板列表加载失败（${res.status}）`);
  const data = (await res.json()) as { templates: TemplateSummary[] };
  return data.templates || [];
}

export async function getTemplate(id: string): Promise<TemplateDetail> {
  const res = await fetch(`${BASE}/api/templates/${encodeURIComponent(id)}`);
  if (!res.ok) throw new Error(`模板加载失败（${res.status}）`);
  return (await res.json()) as TemplateDetail;
}
